import React, { useState, useEffect } from 'react';

interface HealthResponse {
  status: string;
  timestamp: string;
  services: {
    database: string;
    ml_server: string;
    test_environment: string;
  };
}

interface TestsResponse {
  tests: Array<{
    id: string;
    name: string;
    category: string;
    priority: number;
    complexity: string;
    suite: string;
  }>;
  total: number;
  categories: Record<string, number>;
}

function App() {
  const [health, setHealth] = useState<HealthResponse | null>(null);
  const [tests, setTests] = useState<TestsResponse | null>(null);
  const [selectedEnv, setSelectedEnv] = useState(5);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        // Fetch health status
        const healthRes = await fetch('http://localhost:6002/api/health');
        const healthData = await healthRes.json();
        setHealth(healthData);

        // Fetch tests
        const testsRes = await fetch('http://localhost:6002/api/tests');
        const testsData = await testsRes.json();
        setTests(testsData);
      } catch (err) {
        console.error('Failed to fetch data:', err);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
    const interval = setInterval(fetchData, 5000);
    return () => clearInterval(interval);
  }, []);

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-900 text-white flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500 mx-auto mb-4"></div>
          <p className="text-gray-400">Loading test dashboard...</p>
        </div>
      </div>
    );
  }

  const statusColors: { [key: string]: string } = {
    healthy: 'bg-green-500',
    degraded: 'bg-yellow-500',
    down: 'bg-red-500'
  };

  return (
    <div className="min-h-screen bg-gray-900 text-white">
      {/* Header */}
      <header className="bg-gray-800 border-b border-gray-700">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-4">
              <div className="bg-blue-600 p-2 rounded-lg">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
              </div>
              <h1 className="text-2xl font-bold">Test Management Dashboard</h1>
            </div>
            <div className="flex items-center space-x-2 text-sm">
              <span className="text-gray-400">Environment:</span>
              <span className="px-2 py-1 bg-blue-600 rounded">Test</span>
            </div>
          </div>
        </div>
      </header>

      {/* Status Bar */}
      <div className="bg-gray-800 border-b border-gray-700">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-3">
          <div className="grid grid-cols-3 gap-4">
            <div className="flex items-center space-x-2">
              <div className={`w-3 h-3 rounded-full ${health ? statusColors[health.status] : 'bg-gray-500'} animate-pulse`}></div>
              <span className="text-sm">Backend: {health?.status || 'Unknown'}</span>
            </div>
            <div className="flex items-center space-x-2">
              <div className={`w-3 h-3 rounded-full ${health?.services?.database === 'connected' ? 'bg-green-500' : 'bg-red-500'} animate-pulse`}></div>
              <span className="text-sm">Database: {health?.services?.database || 'Unknown'}</span>
            </div>
            <div className="flex items-center space-x-2">
              <div className={`w-3 h-3 rounded-full ${health?.services?.ml_server === 'healthy' ? 'bg-green-500' : 'bg-red-500'} animate-pulse`}></div>
              <span className="text-sm">ML Server: {health?.services?.ml_server || 'Unknown'}</span>
            </div>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Stats Grid */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
          <div className="bg-gray-800 rounded-lg p-6 border border-gray-700">
            <div className="flex items-center justify-between mb-2">
              <span className="text-gray-400 text-sm">Total Tests</span>
              <svg className="w-5 h-5 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
              </svg>
            </div>
            <p className="text-3xl font-bold">{tests?.total || 0}</p>
          </div>

          <div className="bg-gray-800 rounded-lg p-6 border border-gray-700">
            <div className="flex items-center justify-between mb-2">
              <span className="text-gray-400 text-sm">Categories</span>
              <svg className="w-5 h-5 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
              </svg>
            </div>
            <p className="text-3xl font-bold">{tests?.categories ? Object.keys(tests.categories).length : 0}</p>
          </div>

          <div className="bg-gray-800 rounded-lg p-6 border border-gray-700">
            <div className="flex items-center justify-between mb-2">
              <span className="text-gray-400 text-sm">Environments</span>
              <svg className="w-5 h-5 text-purple-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 12h14M5 12a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v4a2 2 0 01-2 2M5 12a2 2 0 00-2 2v4a2 2 0 002 2h14a2 2 0 002-2v-4a2 2 0 00-2-2m-2-4h.01M17 16h.01" />
              </svg>
            </div>
            <p className="text-3xl font-bold">10</p>
          </div>

          <div className="bg-gray-800 rounded-lg p-6 border border-gray-700">
            <div className="flex items-center justify-between mb-2">
              <span className="text-gray-400 text-sm">Active Jobs</span>
              <svg className="w-5 h-5 text-yellow-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
              </svg>
            </div>
            <p className="text-3xl font-bold">0</p>
          </div>
        </div>

        {/* Test Categories */}
        <div className="bg-gray-800 rounded-lg p-6 border border-gray-700 mb-8">
          <h2 className="text-xl font-semibold mb-4">Test Categories</h2>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {tests?.categories && Object.entries(tests.categories).map(([category, count]) => (
              <div key={category} className="flex items-center justify-between p-3 bg-gray-700 rounded-lg">
                <span className="text-sm">{category}</span>
                <span className="text-sm font-semibold text-blue-400">{count}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Recent Tests */}
        <div className="bg-gray-800 rounded-lg p-6 border border-gray-700">
          <h2 className="text-xl font-semibold mb-4">Available Tests</h2>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="text-left border-b border-gray-700">
                  <th className="pb-3 text-gray-400">ID</th>
                  <th className="pb-3 text-gray-400">Name</th>
                  <th className="pb-3 text-gray-400">Category</th>
                  <th className="pb-3 text-gray-400">Priority</th>
                  <th className="pb-3 text-gray-400">Complexity</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-700">
                {tests?.tests.slice(0, 10).map((test) => (
                  <tr key={test.id} className="hover:bg-gray-700 transition-colors">
                    <td className="py-3">{test.id}</td>
                    <td className="py-3">{test.name}</td>
                    <td className="py-3">
                      <span className="px-2 py-1 text-xs bg-gray-700 rounded">
                        {test.category}
                      </span>
                    </td>
                    <td className="py-3">
                      <span className={`px-2 py-1 text-xs rounded ${
                        test.priority === 1 ? 'bg-red-600' : 
                        test.priority === 2 ? 'bg-yellow-600' : 'bg-green-600'
                      }`}>
                        P{test.priority}
                      </span>
                    </td>
                    <td className="py-3">{test.complexity}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </main>
    </div>
  );
}

export default App;
